Our approach is as follows:

\begin{enumerate}
\item Given $\alpha \in (0, 1)$, we construct confidence intervals $\mathrm{\mathrm{CI}}^{(j)}_{1-\alpha, \mathbb{M}}$ for the $j$-th component $\theta_{\mathbb{M}, n}^{*(j)}$ of $\theta_{\mathbb{M}, n}^{*}$, for every $j = 1, \hdots, m(\mathbb{M})$ and every $\mathbb{M} \in \mathsf{M}_n$ so that

\begin{equation*}
\liminf_{n \to \infty} \mathbb{P}_n\left( \theta^{*(j)}_{\mathbb{M}, n} \in \mathrm{CI}^{(j)}_{1-\alpha, \mathbb{M}} \text{ for all } j = 1, \hdots, m(\mathbb{M}) \text{ and all } \mathbb{M} \in \mathsf{M}_n \right)
\end{equation*}

is not smaller than $1-\alpha$.
\item For a model selection procedure $\hat{\mathbb M}_n$, our suggested confidence intervals are then obtained via 

\begin{equation*}
\mathrm{\mathrm{CI}}^{(j)}_{1-\alpha, \hat{\mathbb{M}}_n} \text{ for } j = 1, \hdots, m(\hat{\mathbb{M}}_n).
\end{equation*}

From the coverage property in Part~1 we obtain

\begin{equation*}
\liminf_{n \to \infty} \mathbb{P}_n\left( \theta^{*(j)}_{\hat{\mathbb{M}}_n, n} \in \mathrm{CI}^{(j)}_{1-\alpha, \hat{\mathbb{M}}_n} \text{ for all } j = 1, \hdots, m(\hat{\mathbb{M}}_n) \right) \geq 1-\alpha.
\end{equation*}

\end{enumerate}

Given $\alpha \in (0, 1)$, we construct confidence intervals $\mathrm{\mathrm{CI}}^{(j)}_{1-\alpha, \mathbb{M}}$ for the $j$-th component $\theta_{\mathbb{M}, n}^{*(j)}$ of $\theta_{\mathbb{M}, n}^{*}$, for every $j = 1, \hdots, m(\mathbb{M})$ and every $\mathbb{M} \in \mathsf{M}_n$ so that

\begin{equation*}
\liminf_{n \to \infty} \mathbb{P}_n\left( \theta^{*(j)}_{\mathbb{M}, n} \in \mathrm{CI}^{(j)}_{1-\alpha, \mathbb{M}} \text{ for all } j = 1, \hdots, m(\mathbb{M}) \text{ and all } \mathbb{M} \in \mathsf{M}_n \right)
\end{equation*}

is not smaller than $1-\alpha$.

For a model selection procedure $\hat{\mathbb M}_n$, our suggested confidence intervals are then obtained via 

\begin{equation*}
\mathrm{\mathrm{CI}}^{(j)}_{1-\alpha, \hat{\mathbb{M}}_n} \text{ for } j = 1, \hdots, m(\hat{\mathbb{M}}_n).
\end{equation*}

From the coverage property in Part~1 we obtain

\begin{equation*}
\liminf_{n \to \infty} \mathbb{P}_n\left( \theta^{*(j)}_{\hat{\mathbb{M}}_n, n} \in \mathrm{CI}^{(j)}_{1-\alpha, \hat{\mathbb{M}}_n} \text{ for all } j = 1, \hdots, m(\hat{\mathbb{M}}_n) \right) \geq 1-\alpha.
\end{equation*}

There exist Borel measurable functions $g_{i,n}: {\mathbb R}^{1 \times \ell}\to {\mathbb R}^k$ for $i = 1, \hdots, n$, and $\Delta_n:{\mathbb R}^{n\times \ell}\to{\mathbb R}^k$, possibly depending on $\theta^*_n$, so that for $y\in{\mathbb R}^{n\times \ell}$

\begin{equation} \hat{\theta}_n(y) - \theta_n^*   \quad = \quad  \sum_{i = 1}^n g_{i,n}(y_i) + \Delta_n(y), 
\end{equation}

where, writing $r_n(y) := \sum_{i = 1}^n g_{i,n}(y_i)$, it holds for every $i \in \{1, \hdots, n\}$ and every $j \in \{1, \hdots, k\}$ that

\begin{equation} \mathbb{E}_{i,n}\left(g^{(j)}_{i,n}\right) = 0 \quad \text{ and } \quad 0 < \mathbb{V}_{n}\left(r_n^{(j)} \right) < \infty.
\end{equation}

Furthermore, for every coordinate $j \in \{1, \hdots, k\}$ we have

\begin{equation} \begin{aligned}
&\mathbb{V}_n^{-1}\left(r^{(j)}_n\right)\sum_{i = 1}^n \int_{{\mathbb R}^{1 \times \ell}} \left[g^{(j)}_{i, n}\right]^2 \left\{|g^{(j)}_{i, n}| \geq \varepsilon \mathbb{V}^{\frac{1}{2}}_n(r^{(j)}_n) \right\}  d\mathbb{P}_{i,n} \to 0 \\ &\text{for every } \varepsilon > 0,
\end{aligned}
\end{equation}

and

\begin{equation*}
\mathbb{P}_n \left( \big|\mathbb{V}^{-1/2}_{n}\left(r_n^{(j)} \right) \Delta_n^{(j)} \big| \geq \varepsilon  \right) \to 0 \text{ for every } \varepsilon > 0.
\end{equation*}

\begin{aligned}
&\mathbb{V}_n^{-1}\left(r^{(j)}_n\right)\sum_{i = 1}^n \int_{{\mathbb R}^{1 \times \ell}} \left[g^{(j)}_{i, n}\right]^2 \left\{|g^{(j)}_{i, n}| \geq \varepsilon \mathbb{V}^{\frac{1}{2}}_n(r^{(j)}_n) \right\}  d\mathbb{P}_{i,n} \to 0 \\ &\text{for every } \varepsilon > 0,
\end{aligned}

Under Condition \ref{cond:sum}

\begin{equation*}
d_w\left(\mathbb{P}_n \circ  \left[\mathrm{diag}(\mathbb{V}_n(r_n))^{\dagger/2} \left(\hat{\theta}_n - \theta_n^* \right)\right] , N\left(0, \mathrm{corr}(\mathbb{V}_n(r_n))\right)\right) \to 0,
\end{equation*}

and, for every $\varepsilon > 0$, it holds that

\begin{equation*}
\mathbb{P}_n \left(d_w\left(\mathbb{P}_n \circ  \left[\mathrm{diag}(S_n)^{\dagger/2} \left(\hat{\theta}_n - \theta_n^* \right)\right] , N(0, \mathrm{corr}(S_n))\right) \geq \varepsilon \right) \to 0.
\end{equation*}

Using, e.g., \cite{gnedenko} Theorem 3 in Paragraph 21, one obtains that Equation \eqref{eq:linde} in Condition \ref{cond:sum} can be \emph{equivalently} phrased as

\begin{align*}
\mathbb{P}_n\circ \left( \frac{r_n^{(j)}}{\mathbb{V}^{1/2}_n(r_n^{(j)})} \right) &\Rightarrow N(0, 1) \quad\text{and}\\[7pt]
\max_{i = 1, \hdots, n} \mathbb{P}_n \left(|g_{i,n}^{(j)} | \geq \varepsilon\mathbb{V}^{1/2}_n(r_n^{(j)}) \right) &\to 0\; \text{ for every } \varepsilon > 0.
\end{align*}

In some applications it might be easier to check these two conditions directly (for every $j$), in particular in case one can use existing results in the literature on misspecified models without model selection as indicated above.

Given $\mathbb{M} = \mathbb{M}_{j,n} \in \mathsf{M}_n$ we abbreviate

\begin{equation*}
\rho(\mathbb{M}) \quad := \quad \sum_{l = 1}^{j-1} m(\mathbb{M}_{l,n}),
\end{equation*}

where sums over an empty index set are to be interpreted as $0$.

Let $\alpha \in (0, 1)$, suppose Condition \ref{cond:sum} holds, and let $\hat{S}_n: {\mathbb R}^{n \times \ell} \to {\mathbb R}^{k \times k}$ be a sequence of Borel-measurable functions so that for every $\varepsilon > 0$ 

\begin{equation*} 
\mathbb{P}_n \left( \|\mathrm{corr}(\hat{S}_n) - \mathrm{corr}\left(\mathbb{V}_n(r_n)\right)\|  + \|
\mathrm{diag}(\mathbb{V}_n(r_n))^{-1} \mathrm{diag}(\hat{S}_n) - I_k \| \geq \varepsilon \right)
\end{equation*}

converges to $0$, or equivalently, that for every $\varepsilon > 0$

\begin{equation} \mathbb{P}_n \left( \|\mathrm{corr}(\hat{S}_n) - \mathrm{corr}\left(S_n\right)\|  + \|
\mathrm{diag}(S_n)^{\dagger} \mathrm{diag}(\hat{S}_n) - I_k \| \geq \varepsilon \right) \to 0.
\end{equation}

Define for every $\mathbb{M} \in \mathsf{M}_n$ and every $j = 1, \hdots, m(\mathbb{M})$ the confidence interval

\begin{equation*}
\mathrm{CI}_{1-\alpha, \mathbb{M}}^{(j), \mathrm{est}} \quad = \quad \hat{\theta}^{(j)}_{\mathbb{M}, n} \pm \sqrt{[\hat{S}_n]_{\rho(\mathbb M) + j }} ~  K_{1-\alpha}\left(\mathrm{corr}(\hat{S}_n)\right).
\end{equation*}

Then, 
$
\mathbb{P}_n\left( \theta^{*(j)}_{\mathbb{M}, n} \in \mathrm{CI}_{1-\alpha, \mathbb{M}}^{(j), \mathrm{est}} \text{ for all } \mathbb M\in\mathsf{M}_n \text{ and all } j = 1, \hdots, m(\mathbb{M}) \right) 
$
converges to $1-\alpha$ as $n\to\infty$. In particular, for every (measurable) model selection procedure $\hat{\mathbb{M}}_n$, we have

\begin{equation} \liminf_{n \to \infty} \mathbb{P}_n\left( \theta^{*(j)}_{\hat{\mathbb{M}}_n, n} \in \mathrm{CI}_{1-\alpha, \hat{\mathbb{M}}_n}^{(j), \mathrm{est}} \text{ for all } j = 1, \hdots, m(\hat{\mathbb{M}}_n) \right) \geq 1-\alpha.
\end{equation}

Suppose Condition \ref{cond:sum} is satisfied, and let $\hat{g}_{i,n}: {\mathbb R}^{n \times \ell} \to {\mathbb R}^k$ be Borel measurable for $i = 1, \hdots, n$ and for every $n$. Suppose that for every $j = 1, \hdots, k$ and for every $\varepsilon > 0$ it holds that


\begin{equation} \mathbb{P}_n \left( \frac{\sum_{i = 1}^n \left(g_{i,n}^{(j)} -  \hat{g}_{i,n}^{(j)} \right)^2}{\sum_{i = 1}^n [g_{i,n}^{(j)}]^2} \geq \varepsilon \right) \to 0, 
\end{equation}

or equivalently that 

\begin{equation} \mathbb{P}_n \left( \frac{\sum_{i = 1}^n \left(g_{i,n}^{(j)} -  \hat{g}_{i,n}^{(j)} \right)^2}{\sum_{i = 1}^n \mathbb{V}_n \left( g_{i,n}^{(j)}\right)} \geq \varepsilon \right) \to 0.
\end{equation}

Then the convergence in \eqref{eq:consest} is satisfied for

\begin{equation*}
\hat{S}_n = \sum_{i = 1}^n \hat{g}_{i,n}\hat{g}'_{i,n}.
\end{equation*}

Let $\alpha \in (0, 1)$, and suppose Condition \ref{cond:sum} is satisfied. For every $n$ and every $j = 1, \hdots, k$ let $\hat{\nu}^2_{j,n} \geq 0$ be an estimator of $\mathbb{V}_n(r_n^{(j)})$, and let $\hat{K}_n \geq 0$ be an estimator of $K_{1-\alpha}(\mathrm{corr}(\mathbb{V}_n(r_n)))$, so that the sequence

\begin{equation*}
\kappa_n = \frac{K_{1-\alpha}(\mathrm{corr}(\mathbb{V}_n(r_n)))}{\hat{K}_n} \max_{j = 1, \hdots, k} \sqrt{\frac{[\mathbb{V}_n(r_n)]_{j} }{  \hat{\nu}^2_{j,n} }},
\end{equation*}

satisfies

\begin{equation} \mathbb{P}_n \left( \kappa_n \geq 1+ \varepsilon \right) \to 0 \text{ for every } \varepsilon > 0,
\end{equation}

(implicitly including that $\mathbb{P}_n(\kappa_n \text{ is well defined} ) \to 1$) or, equivalently, that the condition in \eqref{eqn:asptup} holds with $\kappa_n$ replaced by

\begin{equation*}
\frac{K_{1-\alpha}(\mathrm{corr}(S_n))}{\hat{K}_n} \max_{j = 1, \hdots, k} \sqrt{\frac{[S_n]_{j} }{  \hat{\nu}^2_{j,n} }}.
\end{equation*}

For every $\mathbb{M} \in \mathsf{M}_n$ and every $j = 1, \hdots, m(\mathbb{M})$, define the confidence interval

\begin{equation*}
\mathrm{CI}_{1 - \alpha, \mathbb{M}}^{(j), \mathrm{oest}} \quad = \quad \hat{\theta}^{(j)}_{\mathbb{M}, n} \pm \sqrt{\hat{\nu}^2_{\rho(\mathbb M) + j, n}} ~  \hat{K}_n.
\end{equation*}

Then, for every (measurable) model selection procedure $\hat{\mathbb{M}}_n$, we have

\begin{equation*}
\liminf_{n \to \infty} \mathbb{P}_n \left( \theta_{\hat{\mathbb{M}}_n, n}^{*(j)} \in \mathrm{CI}_{1 - \alpha, \hat{\mathbb{M}}_n}^{(j), \mathrm{oest}} \text{ for all } j = 1, \hdots, m(\hat{\mathbb{M}}_n)  \right) \geq 1-\alpha.
\end{equation*}

In the important special case where $\hat{K}_n \geq K_{1-\alpha}(\mathrm{corr}(\mathbb{V}_n(r_n)))$ holds eventually,  the condition in Equation \eqref{eqn:asptup} is implied by the condition that for every $j = 1, \hdots, k$ it holds that

\begin{equation} \mathbb{P}_n \left( \sqrt{\frac{[S_n]_{j} }{  \hat{\nu}^2_{j,n} }} \geq 1+ \varepsilon \right) \to 0 \text{ for every } \varepsilon > 0,
\end{equation}

or equivalently, that for every $j = 1, \hdots, k$ it holds that

\begin{equation} \mathbb{P}_n \left( \sqrt{\frac{[\mathbb{V}_n(r_n)]_{j} }{  \hat{\nu}^2_{j,n} }} \geq 1+ \varepsilon \right) \to 0 \text{ for every } \varepsilon > 0.
\end{equation}

Suppose Condition \ref{cond:sum} is satisfied, and let $\tilde{g}_{i,n}: {\mathbb R}^{n \times \ell} \to {\mathbb R}^k$ and $\hat{g}_{i,n}: {\mathbb R}^{n \times \ell} \to {\mathbb R}^k$ be Borel measurable for $i = 1, \hdots, n$ and for every $n$. Suppose that for every $j = 1, \hdots, k$ and for every $\varepsilon > 0$ the condition \eqref{eq:negldiff}, or equivalently \eqref{eq:negldiff2}, is satisfied. Suppose further that there exist real numbers $a_{i,n}^{(j)}$ so that for $y\in{\mathbb R}^{n\times\ell}$

\begin{equation*}
\tilde{g}^{(j)}_{i,n}(y) \quad = \quad \hat{g}^{(j)}_{i,n}(y) + a_{i,n}^{(j)}
\end{equation*}

holds for every $n \in {\mathbb N}$, $i \in \{1, \hdots, n\}$ and $j \in \{1, \hdots, k\}$. Then the statement in \eqref{eqn:special2} is satisfied for

\begin{equation*}
\hat{\nu}^2_{j,n} \quad = \quad \sum_{i = 1}^n \left[\tilde{g}^{(j)}_{i,n}\right]^2 \quad \text{ for } \quad j = 1, \hdots, k.
\end{equation*}

Using the simple bound $(g_{i,n}^{(j)} - \tilde{g}_{i,n}^{(j)})^2 \le 2(g_{i,n}^{(j)} - \hat{g}_{i,n}^{(j)})^2 + 2 a_{i,n}^2$, it is easy to verify that if the non-stochastic additive components $a_{i,n}$ are negligible in the previously defined sense, then $\tilde{g}_{i,n}$ satisfies the assumptions of $\hat{g}_{i,n}$ appearing in Proposition \ref{prop:obtest}. As a consequence, the estimator 

\begin{equation*}
\tilde{S}_n = \sum_{i = 1}^n \tilde{g}_{i,n}\tilde{g}'_{i,n}
\end{equation*}

satisfies \eqref{eq:consest}, and one can construct confidence intervals based on this estimator as discussed in Theorem \ref{thm:fbl}. Note that $\hat{\nu}^2_{j,n} = [\tilde{S}_n]_{j}$.

The feasible sets for the true underlying distribution $\mathbb{P}_n$ we can allow for in this setup is denoted as $\mathbf{P}_n^{(\mathrm{lm})}\left(\delta, \tau \right)$, where $\delta > 0$ and $\tau \ge 1$, and is defined as follows: the distribution ${\mathbb P}_n$ of the random $n$-vector $Y_n = (Y_{1,n}, \hdots, Y_{n,n})'$ is an element of $\mathbf{P}_n^{(\mathrm{lm})}\left(\delta, \tau \right)$ if and only if the $n$ coordinates of $Y_n$ are independent, homoskedastic (i.e., the variances of the coordinates are equal to some ${\mathbb V}(Y_{i,n}) = \sigma_n^2 \in (0, \infty)$, for all $i=1,\dots, n$), and 

\begin{equation*}
\max_{i = 1, \hdots, n} \mathbb{E}\left(|Y_{i,n} - \mathbb{E}(Y_{i,n})|^{2+\delta}\right)^{\frac{2}{2+\delta}} \leq \tau \sigma_n^2.
\end{equation*}

Eventually $\mathrm{rank}(X_n) = p$, and for every $M\in\mathcal I$,

\begin{equation*}
\max_{i = 1, \hdots, n} X_{i,n}[M] \left( X_{n}[M]'X_{n}[M]  \right)^{-1} X_{i,n}[M]' \to 0.
\end{equation*}

Condition~\ref{cond:X} particularly holds if $\mathrm{rank}(X_n) = p$, eventually, and $\max_{i=1,\dots, n} X_{i,n}(X_n'X_n)^{-1}X_{i,n}' \to 0$. Moreover, it also holds in case $\|X_{i,n}\|$ is bounded and $\lambda_{\min}(\frac{1}{n} X_n'X_n)$ is bounded away from $0$, which is typically the case in sufficiently balanced factorial designs, but Condition~\ref{cond:X} is obviously much more general. For example, it also covers the important cases of polynomial regressors, trigonometric regressors, or mixed polynomial and trigonometric regressors (cf. the discussion in \cite{eicker67}, pp. 64).
Finally, we point out that the condition
\begin{equation*}
\max_{i = 1, \hdots, n} X_{i,n}[M] \left( X_{n}[M]'X_{n}[M]  \right)^{-1} X_{i,n}[M]' \to 0
\end{equation*}
is classical, and is necessary for asymptotic normality of the ordinary-least-squares estimator in the fixed model $\mathbb M$ \citep[see][]{Huber73, Arnold80}.

We shall now describe how asymptotically uniformly valid confidence sets can be constructed post-model-selection for the target defined in Equation \eqref{eqn:targethom} above: Given $\mathbb{M} \in \mathsf{M}_n$ with index set $M$, we estimate the corresponding target by the model-specific ordinary-least-squares estimator, i.e., by

\begin{equation} \hat{\beta}_{\mathbb{M}, n}(y) = \left(X_n[M]'X_n[M]\right)^{-1} X_n[M]'y;
\end{equation}

let

\begin{equation*}
\hat{\sigma}^2_{\mathbb{M}, n}(y) = \frac{1}{n- m(\mathbb{M})} \sum_{i = 1}^n (y_i - X_{i,n}[M] \hat{\beta}_{\mathbb{M}, n}(y) )^2,
\end{equation*}

where $m(\mathbb{M})$ here coincides with $|M|$, the cardinality of $M$, and define for $\alpha \in (0, 1)$ and $j = 1, \hdots, m(\mathbb{M})$

\begin{equation} \mathrm{CI}_{1-\alpha, \mathbb{M}}^{(j), \mathrm{lm}} = \hat{\beta}^{(j)}_{\mathbb{M}, n} \pm  \sqrt{\hat{\sigma}^2_{\mathbb{M}, n} \left[\left( X_n[M]'X_n[M]  \right)^{-1}\right]_j} K_{1-\alpha}(\mathrm{corr}(\Gamma_n)), 
\end{equation}

where the block-matrix $\Gamma_n$ is defined via its $s,t$-th block of dimension $|M_s|\times|M_t|$ given by

\begin{align*}
&{\mathbb E}_n\left[ \left(\hat{\beta}_{\mathbb M_s,n} - \beta^*_{\mathbb M_s,n}\right) \left(\hat{\beta}_{\mathbb M_t,n} - \beta^*_{\mathbb M_t,n}\right)'  \right] \\
&\quad= \sigma_n^2\left( X_n[M_s]' X_n[M_s] \right)^{-1} X_n[M_s]' X_n[M_t] \left( X_n[M_t]' X_n[M_t] \right)^{-1}, 
\end{align*}

for $s, t \in \{1, \hdots, d\}$.

Let $\alpha \in (0, 1)$, $\delta > 0$ and $\tau \ge 1$, suppose Condition~\ref{cond:X} holds, and let $\hat{\mathbb{M}}_n$ be a (measurable) model selection procedure, i.e., a measurable map from the sample space ${\mathbb R}^n$ to $\mathsf{M}_n$. Then

\begin{equation*}
\liminf_{n \to \infty} \inf_{\mathbb{P}_n \in \mathbf{P}_n^{(\mathrm{lm})} \left(\delta, \tau \right)} \mathbb{P}_n \left(\beta_{\hat{\mathbb{M}}_n, n}^{* (j)} \in \mathrm{CI}_{1-\alpha, \hat{\mathbb{M}}_n}^{(j), \mathrm{lm}} \text{ for all } j = 1, \hdots, m(\hat{\mathbb{M}}_n)  \right) \geq 1-\alpha.
\end{equation*}

Finally, to define our confidence intervals in this case, let $\Xi_n$ denote the $d \times d$-dimensional matrix with $s,t$-th entry given by

\begin{equation*}
\sigma_n^2\left[ \left( X_n[M_s]' X_n[M_s] \right)^{-1} X_n[M_s]' X_n[M_t] \left( X_n[M_t]' X_n[M_t] \right)^{-1} \right]_{1}.
\end{equation*}

Given $\alpha \in (0, 1)$, define for every $\mathbb{M} \in \mathsf{M}_n$ with corresponding index set $M$ the confidence interval

\begin{equation*}
\mathrm{CI}_{1-\alpha, \mathbb{M}} = \hat{\eta}_{\mathbb{M}, n} \pm \sqrt{\hat{\sigma}^2_{\mathbb{M}, n} \left[ (X_n[M]'X_n[M])^{-1} \right]_1} K_{1-\alpha}(\mathrm{corr}(\Xi_n)).
\end{equation*}

Let $\alpha \in (0, 1)$, $\delta > 0$ and $\tau \ge 1$, suppose Condition~\ref{cond:X} holds, and let $\hat{\mathbb{M}}_n$ be a (measurable) model selection procedure. Suppose every element of $\mathcal{I}$ contains $1$. Then

\begin{equation*}
\liminf_{n \to \infty} 
\inf_{\mathbb{P}_n \in \mathbf{P}_n^{(\mathrm{lm})} \left(\delta, \tau \right)} \mathbb{P}_n \left(\eta^*_{\hat{\mathbb{M}}_n, n} \in  \mathrm{CI}_{1-\alpha, \hat{\mathbb{M}}_n} \right) \geq 1-\alpha.
\end{equation*}

Fix $\delta>0$ and $\tau\ge 1$ and suppose that eventually $\mathrm{rank}(X_n)=p$. For any sequence ${\mathbb P}_n \in\mathbf{P}_n^{(\mathrm{lm})}(\delta,\tau)$, the variance estimator $\hat{\sigma}_{\mathbb M,n}^2(y) = (n-|M|)^{-1}y'(I_n-P_{X_n[M]})y$ satisfies
\begin{align*}
{\mathbb P}_n\left( \left|\frac{\hat{\sigma}_{\mathbb M,n}^2}{\sigma_n^2} \left(1 + \frac{\|(I_n-P_{X_n[M]})\mu_n/\sigma_n\|^2}{n-|M|}\right)^{-1} - 1\right| > \varepsilon \right)
\;\to\;0,
\end{align*}
for every $\varepsilon>0$ and for every $M\in\mathcal I$.

Let $\delta > 0$ and $\tau > 1$. There does \emph{not} exist a sequence of measurable functions $(\hat{\sigma}^2_{n})_{n \in \mathbb{N}}$ with $\hat{\sigma}^2_{n}: \mathbb{R}^n \to [0, \infty)$, so that for every $\varepsilon > 0$

\begin{equation} \sup_{\mathbb{P}_n \in \mathbf{P}_n^{(\mathrm{lm})}(\delta, \tau)} \mathbb{P}_n \left( \left| \frac{\hat{\sigma}^2_n}{\sigma^2_n} - 1 \right| > \varepsilon \right) \to 0.
\end{equation}

The feasible sets for $\mathbb{P}_n$ we consider here again depend on two parameters $\delta > 0$ and $\tau \ge 1$ but, compared to the set $\mathbf{P}_n^{(\mathrm{lm})} \left(\delta, \tau \right)$ defined above, we now drop the requirement of homoskedasticity: the distribution of a random $n$-vector $Y_n = (Y_{1,n}, \hdots, Y_{n,n})'$ is an element of $\mathbf{P}_n^{(\mathrm{het})} \left(\delta, \tau \right)$ if and only if the $n$ coordinates of $Y_n$ are independent, the variance $\sigma_{i,n}^2 = {\mathbb V}(Y_{i,n}) \in(0,\infty)$ exists for every $i = 1, \hdots, n$, and 

\begin{equation*}
\max_{i = 1, \hdots, n} \left[\mathbb{E}\left(|Y_{i,n} - \mathbb{E}(Y_{i,n})|\right)^{2+\delta}\right]^{\frac{2}{2+\delta}} \leq \tau \min_{i = 1, \hdots, n} \sigma_{i,n}^2.
\end{equation*}

Define for every $\mathbb{M} \in \mathsf{M}_n$ with corresponding index set $M$ the Eicker-estimator $\tilde{S}_{\mathbb M,n}$ as

\begin{equation*}
\left( X_n[M]'X_n[M] \right)^{-1} X_n[M]' \mathrm{diag}\left(\hat{u}^2_{1,\mathbb{M}}, \hdots, \hat{u}^2_{n,\mathbb{M}} \right) X_n[M] \left( X_n[M]'X_n[M] \right)^{-1},
\end{equation*}

where, for $y\in{\mathbb R}^n$, we let $\hat{u}_{\mathbb{M}}(y) = (\hat{u}_{1, \mathbb{M}}(y), \hdots, \hat{u}_{n, \mathbb{M}}(y))' = y - X_n[M] \hat{\beta}_{\mathbb{M}, n}(y)$, and denote the $j-$th diagonal entry ($j = 1, \hdots, m(\mathbb{M})$) of $\tilde{S}_{\mathbb M,n}$ by
$\hat{\sigma}^2_{j,\mathbb{M}, n}$.

Finally, given $\alpha \in (0, 1)$, we define for each $\mathbb{M} \in \mathsf{M}_n$ with corresponding index set $M$ and for every $j = 1, \hdots, m(\mathbb{M})$ the confidence sets

\begin{equation*}
\mathrm{CI}_{1-\alpha, \mathbb{M}}^{(j), \mathrm{hlm}} = \hat{\beta}^{(j)}_{\mathbb{M}, n} \pm  \sqrt{\hat{\sigma}^2_{j,\mathbb{M}, n}} B_{\alpha}(\min(k, p),k),
\end{equation*}

with $k = \sum_{\mathbb M\in\mathsf{M}_n} m(\mathbb{M})$, and where $B_\alpha$ is defined at the end of Section~\ref{sec:overest}.

Let $\alpha \in (0, 1)$, $\delta > 0$ and $\tau \ge 1$, suppose Condition~\ref{cond:X} holds, and let $\hat{\mathbb{M}}_n$ be a (measurable) model selection procedure, i.e., a measurable map from the sample space ${\mathbb R}^n$ to $\mathsf{M}_n$. Then

\begin{equation*}
\liminf_{n \to \infty} \inf_{\mathbb{P}_n \in \mathbf{P}_n^{(\mathrm{het})} 
\left(\delta, \tau \right) } \mathbb{P}_n \left(\beta_{\hat{\mathbb{M}}_n, n}^{* (j)} \in \mathrm{CI}_{1-\alpha, \hat{\mathbb{M}}_n}^{(j), \mathrm{hlm}} \text{ for all } j = 1, \hdots, m(\hat{\mathbb{M}}_n)  \right) \geq 1-\alpha.
\end{equation*}

Let $C>0$ be fixed. Eventually, we have
\begin{enumerate}[(i)]
\item $\mathrm{rank}(X_n) = p$;
\item $\max_{i = 1, \hdots, n} X_{i,n}[M] \left( X_{n}[M]'X_{n}[M]  \right)^{-1} X_{i,n}[M]' \le C/n$, for every $M \in \mathcal{I}$;
\item $\lambda_{\max}(X_n'X_n)/\lambda_{\min}(X_n'X_n) \le C$;
\end{enumerate}

The elements $h\in\mathcal H$ have the following properties:
\begin{enumerate}[(i)]
\item $h:{\mathbb R}\to(0,1)$ is a continuous cumulative distribution function;
\item The functions $\phi_1(\gamma) := \log(h(\gamma))$ and $\phi_2(\gamma) := \log(1-h(\gamma))$ are strictly concave on ${\mathbb R}$;
\item $h$ is twice continuously differentiable and $\phi_1$ and $\phi_2$ have strictly negative second derivatives on ${\mathbb R}$;
\item The derivative $\dot{h}$ of $h$ is strictly positive on ${\mathbb R}$;
\end{enumerate}

The (quasi-)log-likelihood function for model $\mathbb M \triangleq (h,M)$ can be expressed as
\begin{equation*}
\ell_{\mathbb M,n}(y,\beta) \;=\; \sum_{i=1}^n \left[ y_i \phi_1(X_{i,n}[M]\beta) + (1-y_i)\phi_2(X_{i,n}[M]\beta)\right],
\end{equation*}
where $\phi_1(\gamma) = \log h(\gamma)$ and $\phi_2(\gamma) = \log (1-h(\gamma))$, and $y = (y_1,\dots, y_n)'\in\{0,1\}^n$, $\beta\in{\mathbb R}^{|M|}$.

Suppose that $\mathrm{rank}(X_n)=p$ and \ref{cond:H}(\ref{cH:cdf},\ref{cH:concave}) hold. Then, for every $\mathbb M\in\mathsf{M}_n$ and for every ${\mathbb P}_n\in\bigcup_{\delta>0}\mathbf{P}_n^{(\mathrm{bin})}(\delta)$, there exists a unique vector $\beta_{\mathbb M,n}^* = \beta_{\mathbb M,n}^*({\mathbb P}_n)\in{\mathbb R}^{m(\mathbb M)}$, such that 
\begin{equation*}
\int_{{\mathbb R}^n} \ell_{\mathbb M,n}(y,\beta_{\mathbb M,n}^*({\mathbb P}_n)) \,d{\mathbb P}_n(y) \;=\; \sup_{\beta\in{\mathbb R}^{m(\mathbb M)}} \int_{{\mathbb R}^n} \ell_{\mathbb M,n}(y,\beta) \,d{\mathbb P}_n(y).
\end{equation*}

Finally, given $\alpha \in (0, 1)$, we define for each $\mathbb{M} \in \mathsf{M}_n$ and for every $j = 1, \hdots, m(\mathbb{M})$ the confidence sets
