Let $\Gamma_n$ be a sequence of covariance matrices converging to $\Gamma$. By definition, $K_{1-\alpha}(\Gamma_n)$ is the $1-\alpha$-quantile of the distribution of $\|Z_n\|_{\infty}$, where $Z_n$ is a Gaussian random vector with mean $0$ and covariance matrix $\Gamma_n$. By the continuous mapping theorem, $\|Z_n\|_{\infty}$ converges weakly to $\|Z\|_{\infty}$, where $Z$ is a Gaussian random vector with mean $0$ and covariance matrix $\Gamma$. In case $\Gamma \neq 0$ it is easy to see that the distribution function of $\|Z\|_{\infty}$ is everywhere continuous and strictly increasing on $[0,\infty)$, and the result then follows, because weak convergence of distribution functions is equivalent to weak convergence of the corresponding quantile functions. Consider now the case where $\Gamma = 0$. Fix $0 < \varepsilon < 1$. Let $z$ be a random variable taking values in $[0, \infty)$, with continuous and strictly increasing (on $[0,\infty)$) distribution function and $1-\alpha$-quantile equal to $\varepsilon$. Clearly, $\|Z_n\|_{\infty} + z$ converges weakly to $z$. Hence $K_n$, say, the $1-\alpha$ quantile of $\|Z_n\|_{\infty} + z$ converges to $\varepsilon$. From $K_{1-\alpha}(\Gamma_n) \leq K_n$ it then follows that

\begin{equation*}
0 \quad \leq \quad \limsup_{n \rightarrow \infty} K_{1-\alpha}(\Gamma_n) \quad \leq \quad \varepsilon.
\end{equation*}

Therefore, $K_{1-\alpha}(\Gamma_n) \to 0 = K_{1-\alpha}(0)$.

Consider now the case where $\Gamma = 0$. Fix $0 < \varepsilon < 1$. Let $z$ be a random variable taking values in $[0, \infty)$, with continuous and strictly increasing (on $[0,\infty)$) distribution function and $1-\alpha$-quantile equal to $\varepsilon$. Clearly, $\|Z_n\|_{\infty} + z$ converges weakly to $z$. Hence $K_n$, say, the $1-\alpha$ quantile of $\|Z_n\|_{\infty} + z$ converges to $\varepsilon$. From $K_{1-\alpha}(\Gamma_n) \leq K_n$ it then follows that

\begin{equation*}
0 \quad \leq \quad \limsup_{n \rightarrow \infty} K_{1-\alpha}(\Gamma_n) \quad \leq \quad \varepsilon.
\end{equation*}

For $n \in {\mathbb N}$, for every $i = 1, \hdots, n$, and for $j = 1, 2$, let  $a_{i,n}(j)$ and $b_{i,n}(j)$ be random variables on a probability space $(\Omega_n, \mathcal{A}_n, \mathbb{P}_n)$. Furthermore, let $a_{i,n}=a_{i,n}(1)$ and $b_{i,n}=b_{i,n}(1)$.

\begin{enumerate}
\item If $\mathbb{P}_n(\sum_{i = 1}^n a^2_{i,n} = 0) \to 0$ holds, and if $\frac{\sum_{i = 1}^n (a_{i,n} - b_{i,n})^2}{\sum_{i = 1}^n a^2_{i,n} } = o_{\mathbb{P}_n}(1)$, then 

\begin{equation}
\mathbb{P}_n \left( \bigg| \frac{\sum_{i = 1}^n b^2_{i,n} }{\sum_{i = 1}^n  a^2_{i,n}} - 1 \bigg| \geq \varepsilon \right) \to 0 \quad \text{ for every } \varepsilon > 0.
\end{equation}

\item If $\mathbb{P}_n(\sum_{i = 1}^n a^2_{i,n}(j) = 0) \to 0$ and $\frac{\sum_{i = 1}^n (a_{i,n}(j) - b_{i,n}(j))^2}{\sum_{i = 1}^n a^2_{i,n}(j) } = o_{\mathbb{P}_n}(1)$ holds for $j = 1, 2$, then for every $\varepsilon > 0$ 

\begin{align}
&\mathbb{P}_n \bigg( \bigg | \frac{\sum_{i = 1}^n a_{i,n}(1)  a_{i,n}(2)}{\sqrt{\sum_{i = 1}^n  a_{i,n}^2(1) } \sqrt{  \sum_{i = 1}^n  a^2_{i,n}(2)}} 
\\[7pt] & \hspace{3cm}  - \quad  \frac{\sum_{i = 1}^n b_{i,n}(1)  b_{i,n}(2)}{\sqrt{\sum_{i = 1}^n  b_{i,n}^2(1)}  \sqrt{\sum_{i = 1}^n  b^2_{i,n}(2)}} \bigg | \geq \varepsilon \bigg) \to 0.
\end{align}

\item Suppose that $\mathbb{V}_n(\sum_{i = 1}^n a_{i,n}) > 0$ holds eventually. Assume that for every $n$ the random variables $a_{i,n}$ for $i = 1, \hdots, n$ have mean $0$ and are uncorrelated, and that it holds that  

\begin{equation} \mathbb{P}_n\left(\bigg|\frac{\sum_{i = 1}^n a^2_{i,n}}{\mathbb{V}_n(\sum_{i = 1}^n a_{i,n})} - 1\bigg| > \varepsilon\right) \to 0 \text{ for every } \varepsilon > 0,
\end{equation}

that

\begin{equation} \frac{\max_{i = 1, \hdots, n} \mathbb{V}_n(a_{i,n})}
{\mathbb{V}_n(\sum_{i = 1}^n a_{i,n})} \to 0,
\end{equation}

and that $\frac{\sum_{i = 1}^n (a_{i,n} - b_{i,n})^2}{\sum_{i = 1}^n a^2_{i,n} } = o_{\mathbb{P}_n}(1)$. Then for every array of real numbers $c_{i,n}$ we have

\begin{equation}
\mathbb{P}_n \left(  \frac{\sum_{i = 1}^n (b_{i,n} + c_{i,n})^2}{\mathbb{V}_n(\sum_{i = 1}^n a_{i,n})} \leq 1 - \varepsilon \right) \to 0 \quad \text{ for every } \varepsilon > 0.
\end{equation}

\end{enumerate}

For the first part note that the quotient under consideration is well defined with probability converging to one, that

\begin{equation}
\frac{\sum_{i = 1}^n b^2_{i,n} }{\sum_{i = 1}^n  a^2_{i,n}} - 1 = o_{\mathbb{P}_n}(1) + 2 \frac{\sum_{i = 1}^n  a_{i,n} [b_{i,n} - a_{i,n}]}{\sum_{i = 1}^n  a^2_{i,n}},
\end{equation}

and that by the Cauchy-Schwarz inequality 

\begin{equation}
\bigg| \frac{\sum_{i = 1}^n  a_{i,n} [b_{i,n} - a_{i,n}]}{\sum_{i = 1}^n  a^2_{i,n}} \bigg|
\leq 
\sqrt{\frac{\sum_{i = 1}^n (a_{i,n} - b_{i,n})^2}{\sum_{i = 1}^n  a^2_{i,n}}} = o_{\mathbb{P}_n}(1).
\end{equation}

For the second part note that the quotients are well defined with probability converging to 1 (by applying Part 1), and write

\begin{equation}
\frac{\sum_{i = 1}^n a_{i,n}(1)  a_{i,n}(2)}{\sqrt{\sum_{i = 1}^n  a_{i,n}^2(1) } \sqrt{  \sum_{i = 1}^n  a^2_{i,n}(2)}} - \frac{\sum_{i = 1}^n b_{i,n}(1)  b_{i,n}(2)}{\sqrt{\sum_{i = 1}^n  b_{i,n}^2(1)}  \sqrt{\sum_{i = 1}^n  b^2_{i,n}(2)}}
\end{equation}

as the sum of

\begin{align}
