\mathbb{Q}_{n''} := \mathbb{P}_{n''} \circ F(\bar{r}_{{n''}, *}, \mathrm{corr}(\hat{S}_{n''})) \Rightarrow Q_{\bar{\Sigma}} \circ \left(\|.\|_{\infty} - K_{1-\alpha}(\bar{\Sigma})\right).
\end{equation}

