= \quad &\mathbb{Q}_{n''} \left((-\infty, 0]  \right)
\to Q_{\bar{\Sigma}} \left(y \in {\mathbb R}^k: \|y\|_{\infty} \leq K_{1-\alpha}(\bar{\Sigma})\right) = 1-\alpha.
\end{align}

