To show that $(n-m)^{-1}\sum_{i=1}^n (H_M)_{ii} v_{i,n}^2$ converges to one, we use a standard truncation argument. For $K>0$ define $\tilde{v}_{i,n} = v_{i,n}\{|v_{i,n}|\le K\}$, $S_n = \frac{1}{n-m}\sum_{i=1}^n(H_M)_{ii} v_{i,n}^2$, $\tilde{S}_n = \frac{1}{n-m}\sum_{i=1}^n(H_M)_{ii} \tilde{v}_{i,n}^2$ and
\begin{align*}
D_n &:= S_n - \tilde{S}_n 
=
\frac{1}{n-m}\sum_{i=1}^n(H_M)_{ii} v_{i,n}^2\{|v_{i,n}|>K\} \;\ge\; 0.
\end{align*}

Using first H\"older's inequality, and then Markov's inequality (recall that $\mathbb{E}(v^2_{i,n}) = 1$), $\max_{i = 1, \hdots, n} \left({\mathbb E}_n[|v_{i,n}|^{2+\delta}]\right)^{2/(2+\delta)} \leq \tau$ (recall that ${\mathbb P}_n\in\mathbf{P}_n^{(\mathrm{lm})}(\delta,\tau)$), and $\mathrm{trace}(H_M) = n-m$, the mean of $D_n$ can be bounded by

\begin{align*}
{\mathbb E}_n[D_n] &\le \frac{1}{n-m}\sum_{i=1}^n(H_M)_{ii} \left({\mathbb E}_n[|v_{i,n}|^{2+\delta}]\right)^{2/(2+\delta)}{\mathbb P}_n(|v_{i,n}|^2>K^2)^{\delta/(2+\delta)}\\
&\le 
\tau K^{-\frac{2\delta}{2+\delta}}.
\end{align*}

Therefore, we can write
\begin{align*}
\frac{\hat{\sigma}_{\mathbb M,n}^2}{\sigma_n^2} 
=
\frac{\hat{\sigma}_{\mathbb M,n}^2}{{\mathbb E}_n[\hat{\sigma}_{\mathbb M,n}^2]} \frac{{\mathbb E}_n[\hat{\sigma}_{\mathbb M,n}^2]}{\sigma_n^2}
=
(1+o_{{\mathbb P}_n}(1))  
\left(
\frac{(\mu_n/\sigma_n)'H_M(\mu_n/\sigma_n)}{n-m} + 1
\right),
\end{align*}
which finishes the proof.\hfill\qed

For every $n \in {\mathbb N}$, let $\mathbb{P}_n \in \mathbf{P}_n^{(\mathrm{lm})}(\delta, \tau)$. Abbreviate $u_{i,n}(y_i) := y_i - \mu_{i,n}$, and $u_n(y) = (u_{1,n}(y_1), \hdots, u_{n,n}(y_n))'$, where $y=(y_1,\dots, y_n)'\in{\mathbb R}^n$ and $\mu_n = (\mu_{1,n},\dots, \mu_{n,n})'$. We note that by assumption

\begin{equation} \frac{\max_{i = 1, \hdots, n} \mathbb{E}_{i,n} (|u_{i,n}|^{2+\delta})^{\frac{2}{2+\delta}}}{\sigma_n^2} \leq \tau.
\end{equation}

We now verify Condition \ref{cond:sum} (with $\Delta_n \equiv  0$): Since this condition is formulated in a component-wise fashion, it suffices to verify it for an arbitrary component $j\in\{1,\dots, m(\mathbb M)\}$ of the estimation error $r_{n,\mathbb M}$ in an arbitrary model $\mathbb M\in\mathsf{M}_n$ with corresponding index set $M\in\mathcal I$. Recall that 

\begin{equation}
\beta_{\mathbb{M}, n}^{*} = \left(X_n[M]' X_n[M] \right)^{-1} X_n[M]'\mu_n = U_n^{-1} X_n[M]'\mu_n,
\end{equation}

for $U_n := X_n[M]' X_n[M] $. The $j$-th coordinate of the estimation error

\begin{equation}
r_{n,\mathbb M}(y) \;:=\;  \hat{\beta}_{\mathbb M,n}(y) - \beta_{\mathbb{M}, n}^{*}  = U_n^{-1}X_n[M]'u_n(y)
\end{equation}

can be written as

\begin{equation}
\sum_{i = 1}^n e_{|M|}'(j)U_n^{-1} X_{i,n}[M]' u_{i,n}(y_i) =: \sum_{i=1}^n g^{(j)}_{i,n,\mathbb M}(y_i),
\end{equation}

where $e_m(j)$ denotes the $j$-th element of the canonical basis of ${\mathbb R}^m$. 
By definition $\mathbb{E}_{i,n} \left( g_{i,n,\mathbb M}^{(j)} \right) = 0$  and $0 < \mathbb{V}_{n} \left( r_{n,\mathbb M}^{(j)} \right) < \infty$ holds (eventually), the latter following from

\begin{equation} \mathbb{V}_{n} \left( r_{n,\mathbb M} \right) = \sigma_n^2 U_n^{-1}
\end{equation}

together with Condition~\ref{cond:X}. We now verify that for every $\varepsilon > 0$ it holds that

\begin{equation} \mathbb{V}_n^{-1}\left(r_{n,\mathbb M}^{(j)}\right) \sum_{i = 1}^n \int_{\mathbb R} \left[ g_{i,n,\mathbb M}^{(j)}\right]^2 \left\{ |g_{i,n,\mathbb M}^{(j)}| \geq \varepsilon \mathbb{V}_n^{\frac{1}{2}}\left(r_{n,\mathbb M}^{(j)}\right) \right\} d \mathbb{P}_{i,n} \to 0.
\end{equation}

An application of H\"older's inequality (with $p = \frac{2+\delta}{2}$ and $q = \frac{2+\delta}{\delta}$) shows that the quantity to the left in the previous display is bounded from above by

\begin{equation}
\frac{\max_{i = 1, \hdots, n} \mathbb{E}_{i,n} (|u_{i,n}|^{2+\delta})^{\frac{2}{2+\delta}}}{\sigma_n^2}\left( \max_{i = 1, \hdots, n} \mathbb{P}_{i,n} \left( | g_{i,n,\mathbb M}^{(j)}  | \geq \varepsilon \mathbb{V}_n^{\frac{1}{2}}\left(r_{n,\mathbb M}^{(j)}\right) \right) \right)^{\frac{\delta}{2 + \delta}} ,
\end{equation}

which, using the bound \eqref{eqn:astau} and Markov's inequality, does not exceed

\begin{equation} \tau ~ \left( 
\frac{\max_{i = 1, \hdots, n}  \left( U_n^{-1}X_{i,n}[M]'X_{i,n}[M]U_n^{-1}\right)_{j} }{ \left( U_n^{-1}\right)_{j}}
\right)^{\frac{\delta}{2 + \delta}} ~ \varepsilon^{-\frac{2\delta}{2 + \delta}} .
\end{equation}

Finally, since the term within brackets coincides with

\begin{equation}
\max_{i = 1, \hdots, n} \bigg( X_{i,n}[M] U_n^{-\frac{1}{2}} \frac{W_{j,n}}{\|W_{j,n}\|} 
U_n^{-\frac{1}{2}} X_{i,n}[M]' \bigg),
\end{equation}

for 

\begin{align}
W_{j,n} = 
U_n^{-\frac{1}{2}} e_{|M|}(j) e'_{|M|}(j) U_n^{-\frac{1}{2}},
\end{align}

and since this quantity is not greater than

\begin{equation}
\max_{i = 1, \hdots, n} X_{i,n}[M]U_n^{-1} X_{i,n}[M]' \to 0,
\end{equation}

where convergence holds by Condition \ref{cond:X}, the statement in \eqref{eqn:lindehomreg} follows. Since $\mathbb M$ and $j$ were arbitrary, we have verified Condition~\ref{cond:sum}. 

Now, for $\mathbb M$, $M$ and $j$ as before, set $\hat{\nu}_{j,n,\mathbb M}^2 = \hat{\sigma}_{\mathbb M,n}^2 (U_n^{-1})_{j}$. Thus, using \eqref{eqn:varhomlin} and Proposition~\ref{prop:lmvarest}, we see that

\begin{align*}
\mathbb{P}_n \left( \sqrt{ \frac{[\mathbb{V}_n(r_{n,\mathbb M})]_j
}{\hat{\nu}_{j,n,\mathbb M}^2 }} \geq 1+\varepsilon   \right) 
=
\mathbb{P}_n \left( \sqrt{ \frac{\sigma_n^2
}{\hat{\sigma}_{\mathbb M,n}^2 } } \geq 1+\varepsilon   \right) 
\to 0.
\end{align*}

Finally, note that for the stacked vector $r_n = (r_{n,\mathbb M_1}',\dots, r_{n,\mathbb M_d}')'$, we have

\begin{equation}
