\frac{\|X_n[M](X_n[M]'X_n[M])^{-1}X_n[M]'\|}{\min_{i=1,\dots, n}(-y_i\ddot{\phi}_1(X_{i,n}[M]\beta_{\mathbb M,n}^*) - (1-y_i)\ddot{\phi}_2(X_{i,n}[M]\beta_{\mathbb M,n}^*))} \times\notag\\
&\quad\quad\quad
\sup_{\beta\in N_{\mathbb M,{\mathbb P}_n,n}(\delta)}\max_{\substack{i=1,\dots, n\\j=1,2}} |\ddot \phi_j(X_{i,n}[M]\beta) - \ddot \phi_j(X_{i,n}[M]\beta_{\mathbb M,n}^*)|. \end{align}

We have just seen that the minimum on the far right side of the previous display is lower bounded by a positive constant that depends only on $\tau$ and $C$. To finish the proof, note that for $\beta\in N_{\mathbb M,{\mathbb P}_n,n}(\delta)$, we have 
\begin{align*}
&|X_{i,n}[M]\beta - X_{i,n}[M]\beta_{\mathbb M,n}^*| \\ &\le \|X_{i,n}[M](X_n[M]'X_n[M])^{-1/2}\| \|(X_n[M]'X_n[M])^{1/2}(\beta - \beta_{\mathbb M,n}^*)\|\le \delta \sqrt{C/n}
\end{align*} 
and that $|X_{i,n}[M]\beta_{\mathbb M,n}^*|\le K^*(\tau,C)$, by Lemma~\ref{lemma:pseudoBound}. Therefore, by uniform continuity of $\ddot{\phi}_j$ on the compact interval $[-K^*(\tau,C) - \delta \sqrt{C}, K^*(\tau,C) + \delta \sqrt{C}]$, for every $\eta>0$, there exists $n_0 = n_0(\eta, \tau, \delta, C,h)$, such that the supremum in \eqref{eq:Hcontinuity} is bounded by $\eta$, for all $n\ge n_0$. Since $\mathcal H$ is finite, the proof of \ref{l:Hcont:B} is finished.

The proof is a variation of the consistency part of the proof of Theorem~4 in \citet{Fahrmeir90}. 
Fix $n$ large enough, such that the bound of Condition~\ref{cond:X2}\eqref{cX2:Huber} holds, the pseudo parameter of Lemma~\ref{lemma:pseudo} exists and the bound of Lemma~\ref{lemma:pseudoBound} applies. Fix $\mathbb M\in\mathsf{M}_n$ and ${\mathbb P}_n\in\mathbf{P}_n^{(\mathrm{bin})}(\tau)$, write $\beta_{\mathbb M,n}^* = \beta_{\mathbb M,n}^*({\mathbb P}_n)$ and note that by Condition~\ref{cond:H}\eqref{cH:C2}, the function $\beta\mapsto \ell_{\mathbb M,n}(y,\beta)$ is twice continuously differentiable on ${\mathbb R}^{m(\mathbb M)}$ and thus, for every $y\in\{0,1\}^n$, admits the expansion
\begin{align*}
\ell_{\mathbb M,n}(y,\beta) \quad&=\quad \ell_{\mathbb M,n}(y,\beta_{\mathbb M,n}^*) \;+\; (\beta-\beta_{\mathbb M,n}^*)'U_{M,n}^{1/2}U_{M,n}^{-1/2}s_{\mathbb M,n}^*(y) \\
&\quad-\; \frac{1}{2}(\beta-\beta_{\mathbb M,n}^*)'U_{M,n}^{1/2}U_{M,n}^{-1/2}H_{\mathbb M,n}(y,\tilde{\beta}_n)U_{M,n}^{-1/2}U_{M,n}^{1/2}(\beta-\beta_{\mathbb M,n}^*), 
\end{align*}
for some $\tilde{\beta}_n\in\{a\beta + (1-a)\beta_{\mathbb M,n}^* : a\in[0,1]\}$, and where $s_{\mathbb M,n}^*(y) = \frac{\partial \ell_{\mathbb M,n}(y,\beta)}{\partial \beta}\Big|_{\beta=\beta_{\mathbb M,n}^*}$, $H_{\mathbb M,n}(y,\beta) = -\frac{\partial \ell_{\mathbb M,n}(y,\beta)}{\partial\beta\partial\beta'}$, and $U_{M,n} = X_n[M]'X_n[M]/n$. 
For $\delta>0$, define $\lambda_n = \sqrt{n}U_{M,n}^{1/2}(\beta-\beta_{\mathbb M.n}^*)/\delta$ to rewrite the previous equation as
\begin{align*}
\ell_{\mathbb M,n}(y,\beta) \;-\; \ell_{\mathbb M,n}(y,\beta_{\mathbb M,n}^*) \;&=\; \delta \lambda_n'U_{M,n}^{-1/2}s_{\mathbb M,n}^*(y)/\sqrt{n} \\
&\quad-\; \frac{1}{2}\delta^2 \lambda_n'U_{M,n}^{-1/2}(H_{\mathbb M,n}(y,\tilde{\beta}_n)/n)U_{M,n}^{-1/2}\lambda_n,
\end{align*}
for all $\beta\in{\mathbb R}^{m(\mathbb M)}$ and all $y\in\{0,1\}^n$. For $N_n(\delta) := N_{\mathbb M,{\mathbb P}_n,n}(\delta)$ as in Lemma~\ref{lemma:Hcontinuity}\ref{l:Hcont:B}, define 
$
L_n(y,\delta) := \inf_{\beta\in N_n(\delta)} \lambda_{\min}\left(U_{M,n}^{-1/2}(H_{\mathbb M,n}(y,\beta)/n)U_{M,n}^{-1/2}\right), 
$
take $\beta\in\partial N_n(\delta) = \{\beta\in{\mathbb R}^{m(\mathbb M)} : \|\sqrt{n}U_{M,n}^{1/2}(\beta-\beta_{\mathbb M,n}^*)\|= \delta\}$ and observe that now $\|\lambda_n\|=1$, $\delta\lambda_n'U_{M,n}^{-1/2}s_{\mathbb M,n}^*(y)/\sqrt{n} \le \delta \|U_{M,n}^{-1/2}s_{\mathbb M,n}^*(y)/\sqrt{n}\|$ and 
\begin{align*}
\frac{1}{2}\delta^2 L_n(y,\delta) \;&\le\; \frac{1}{2}\delta^2 \lambda_{\min}\left(U_{M,n}^{-1/2}(H_{\mathbb M,n}(y,\tilde{\beta})/n)U_{M,n}^{-1/2}\right) \\
\;&\le\; \frac{1}{2}\delta^2 \lambda_n'U_{M,n}^{-1/2}(H_{\mathbb M,n}(y,\tilde{\beta})/n)U_{M,n}^{-1/2}\lambda_n,
\end{align*}
for all $y\in\{0,1\}^n$.
Therefore, we have the inclusion 
\begin{align*}
E_{\mathbb M,{\mathbb P}_n,n}(\delta) &:= \{y\in\{0,1\}^n:\delta\|U_{M,n}^{-1/2}s_{\mathbb M,n}^*(y)/\sqrt{n}\| < \delta^2 L_n(y,\delta)/2\} \\
&\subseteq \{y\in\{0,1\}^n : \forall \beta\in\partial N_n(\delta) : \ell_{\mathbb M,n}(y,\beta) < \ell_{\mathbb M,n}(y,\beta_{\mathbb M,n}^*)\} =: F_n(\delta).
\end{align*}
As a consequence, for every $y \in E_{\mathbb M,{\mathbb P}_n,n}(\delta)$, the function $\beta\mapsto \ell_{\mathbb M,n}(y,\beta)$ has a local maximum $\hat{\beta}_{\mathbb M,n}(y)$ on the interior of $N_n(\delta)$. By strict concavity (Conditions~\ref{cond:H}\eqref{cH:concave} and \ref{cond:X2}\eqref{cX2:rank}), this is a unique global maximum. 
Moreover, we have $F_n(\delta) \subseteq \{y: \hat{\beta}_{\mathbb M,n}(y) \in N_n(\delta)\} = \{y: \|\sqrt{n}U_{M,n}^{1/2}(\hat{\beta}_{\mathbb M,n}(y) - \beta_{\mathbb M,n}^*)\| \le \delta\}$. Hence, 
$$
{\mathbb P}_n(\|\sqrt{n}U_{M,n}^{1/2}(\hat{\beta}_{\mathbb M,n}(y) - \beta_{\mathbb M,n}^*)\| > \delta)
\;\le\;
{\mathbb P}_n(E_{\mathbb M,{\mathbb P}_n,n}(\delta)^c).
$$
It remains to verify that ${\mathbb P}_n(E_{\mathbb M,{\mathbb P}_n,n}(\delta)^c)$ is small for large $n$, uniformly in $\mathbb M$ and ${\mathbb P}_n$. Take $\varepsilon>0$ and note that
\begin{align}
{\mathbb P}_n(E_{\mathbb M,{\mathbb P}_n,n}(\delta)^c) \;&\le\; \notag
{\mathbb P}_n(4\|U_{M,n}^{-1/2}s_{\mathbb M,n}^*(\cdot)/\sqrt{n}\|^2\ge \delta^2 L_n^2(\cdot,\delta), L_n^2(\cdot,\delta) \ge \varepsilon^2 ) \notag\\
&\;\quad\;+\; {\mathbb P}_n(L_n^2(\cdot,\delta) < \varepsilon^2 ) \\
&\le \;
{\mathbb P}_n(4\|U_{M,n}^{-1/2}s_{\mathbb M,n}^*(\cdot)/\sqrt{n}\|^2\ge \delta^2 \varepsilon^2) \;+\; {\mathbb P}_n(L_n^2(\cdot,\delta) < \varepsilon^2 )\notag\\
&\le \;
4\frac{\mathrm{trace}(U_{M,n}^{-1/2}{\mathbb{V}}_n(s_{\mathbb M,n}^*/\sqrt{n})U_{M,n}^{-1/2})}{\delta^2\varepsilon^2} \;+\; {\mathbb P}_n(L_n(\cdot,\delta) < \varepsilon ), \notag
\end{align}
in view of Markov's inequality and since ${\mathbb E}_n[s_{\mathbb M,n}^*] = 0$. Note that ${\mathbb{V}}_n(s_{\mathbb M,n}^*) = X_n[M]'V_{\mathbb M,{\mathbb P}_n,n}^*X_n[M]$, for a diagonal matrix $V_{\mathbb M,{\mathbb P}_n,n}^*$ whose diagonal entries satisfy 
\begin{align*}
[V_{\mathbb M,{\mathbb P}_n,n}^*]_{ii} \;&=\; {\mathbb P}_{i,n}(\{1\}){\mathbb P}_{i,n}(\{0\})(\dot{\phi}_1(X_{i,n}\beta_{\mathbb M,n}^*) - \dot{\phi}_2(X_{i,n}\beta_{\mathbb M,n}^*))^2 \\
\;&\le\; \sup_{|\gamma|\le K^*(\tau,C)}(\dot{\phi}_1(\gamma) - \dot{\phi}_2(\gamma))^2,
\end{align*}
for the constant $K^*(\tau,C)$ of Lemma~\ref{lemma:pseudoBound}.
Thus, the trace on the last line of display~\eqref{eq:lUnifCons:trace} is bounded by $p\max_{h\in\mathcal H}\sup_{|\gamma|\le K^*(\tau,C)}(\dot{\phi}_1(\gamma) - \dot{\phi}_2(\gamma))^2$, which does not depend on $n$, $\mathbb M$ or ${\mathbb P}_n$. Finally, to bound the remaining probability, note that $L_n(y,\delta)$ is lower bounded by the product of $\lambda_{\min}(U_{M,n}^{-1/2}H_{\mathbb M,n}^*(y)U_{M,n}^{-1/2})/n$ and  $\inf_{\beta\in N_n(\delta)}  \lambda_{\min}(H_{\mathbb M,n}^*(y)^{-1/2}H_{\mathbb M,n}(y,\beta)H_{\mathbb M,n}^*(y)^{-1/2})$. The first factor is itself lower bounded by the positive constant $\underline{K}(\tau, C)$ from Lemma~\ref{lemma:Hcontinuity}\ref{l:Hcont:A}. Thus, ${\mathbb P}_n(L_n(\cdot,\delta) < \varepsilon )$ is upper bounded by
$$
{\mathbb P}_n\left( 
\sup_{\beta\in N_{n}(\delta)} \left\| H_{\mathbb M,n}^*(y)^{-1/2}H_{\mathbb M,n}(y,\beta)H_{\mathbb M,n}^*(y)^{-1/2} - I_{m(\mathbb M)} \right\| > 1- \frac{\varepsilon}{\underline{K}(\tau, C)}
\right).
$$
Choosing $\varepsilon = \underline{K}(\tau, C)/2$ and using Lemma~\ref{lemma:Hcontinuity}\ref{l:Hcont:B}, we conclude that for every $\delta>0$,
\begin{align}
&\sup_{\mathbb M\in\mathsf{M}_n}\sup_{{\mathbb P}_n\in\mathbf{P}_n^{(\mathrm{bin})}(\tau)} 
{\mathbb P}_n\left( 
	\left\| (X_n[M]'X_n[M])^{1/2}(\hat{\beta}_{\mathbb M,n} - \beta^*_{\mathbb M,n}({\mathbb P}_n))\right\| > \delta\right) \\
&\quad\le	
\sup_{\mathbb M\in\mathsf{M}_n}\sup_{{\mathbb P}_n\in\mathbf{P}_n^{(\mathrm{bin})}(\tau)} 
{\mathbb P}_n(E_{\mathbb M,{\mathbb P}_n,n}(\delta)^c)\\	
&\quad\le 
16\frac{p\max_{h\in\mathcal H}\sup_{|\gamma|\le K^*(\tau,C)}(\dot{\phi}_1(\gamma) - \dot{\phi}_2(\gamma))^2}{\delta^2\underline{K}(\tau,C)^2}	
+
o(1),
\end{align}
where the $o(1)$ term refers to convergence as $n\to\infty$.
